var t = $feature.to_name;
var m = IIf($feature.on_ship == 'nein',
  When(t == 'Vancouver', 'Über den Pazifik mit der „Empress of China“ (Canadian Pacific Railway Company); Letzter Tag an Bord der Elisabeth laut Tagebuch: 24.8.1893 in Yokohama.',
       t == 'Le Havre', 'Über den Atlantik mit der „Bretagne“ (Tagebuch).',
       'Ohne die Elisabeth, über Land.'),
  'Abschnitt der Reise mit der Kaiserin Elisabeth. Ob zu Schiff oder über Land, zeigt die Linie nicht.');
m + IIf($feature.estimated == 1, ' Datum geschätzt.', '') + ' Die Linie ist eine Luftlinie, nicht der Weg.'

labelExpressionInfo.expression:
function p(s) { var t = Lower(s); for (var k in ['ā','ī','ū','ō','ē']) { t = Replace(t, ['ā','ī','ū','ō','ē'][k], ['a','i','u','o','e'][k]); } return t; }
var a = $feature.name_then; var b = $feature.name_now;
IIf(!IsEmpty(b) && p(a) != p(b), a + ' (' + b + ')', a)

